challenge.solution:
.grid { grid-template-columns: repeat(2, 1fr); }
.card:first-child { grid-column: 1 / -1; background: #f1f5f9; }
.card:first-child h2 { font-size: 22px; }

p {
  font-size: 1.125rem;   /* 18px */
  line-height: 1.6;
  max-width: 65ch;
  color: #1e293b;        /* dark enough for strong contrast */
}
